import { forwardRef } from "react";
import { PlateContent, type PlateContentProps } from "platejs/react";
import { clsx } from "clsx";

import { RichTextClasses } from "../rich-text.styles";

export const RichTextContent = forwardRef<HTMLDivElement, PlateContentProps>(
  ({ className, ...props }, ref) => {
    return (
      <PlateContent ref={ref} className={clsx(RichTextClasses.content, className)} {...props} />
    );
  },
);

RichTextContent.displayName = "RichText.Content";
